/**
 * Benchmark v1 generator (AIA-09): ≥ 5,200 labelled synthetic transactions with realistic statement noise,
 * stratified 80/20 train/test per category. Deterministic (seeded), so the committed files can be
 * regenerated byte-for-byte: `pnpm --filter @montra/ai-gateway exec tsx eval/generate.ts`.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export interface BenchCategory {
  id: string;
  name: string;
  group: string;
  kind: 'income' | 'expense';
  entityType: 'personal' | 'business' | 'rental';
}

export interface BenchRow {
  id: string;
  split: 'train' | 'test';
  entityType: BenchCategory['entityType'];
  accountType: string;
  payee: string;
  description: string;
  amountMinor: string;
  currency: string;
  date: string;
  label: string;
}

interface Spec {
  cat: Omit<BenchCategory, 'id'>;
  merchants: string[];
  /** Amount range in dollars; negative = money out. */
  range: [number, number];
  accounts: string[];
}

