const CITIES: [string, string][] = [
  ['SAN FRANCISCO', 'CA'],
  ['NEW YORK', 'NY'],
  ['AUSTIN', 'TX'],
  ['SEATTLE', 'WA'],
  ['CHICAGO', 'IL'],
  ['DENVER', 'CO'],
  ['BOSTON', 'MA'],
  ['ATLANTA', 'GA'],
  ['PORTLAND', 'OR'],
  ['MIAMI', 'FL'],
];

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function generateBenchmark(seed = 20261030): { categories: BenchCategory[]; rows: BenchRow[] } {
  const rand = mulberry32(seed);
  const pick = <T>(xs: readonly T[]): T => xs[Math.floor(rand() * xs.length)]!;
  const digits = (n: number) => Array.from({ length: n }, () => Math.floor(rand() * 10)).join('');
  const categories: BenchCategory[] = SPECS.map((s) => ({
    id: s.cat.name.toLowerCase().replace(/[^a-z]+/g, '-'),
    ...s.cat,
  }));

  const noisy = (name: string, date: string): string => {
    const [city, st] = pick(CITIES);
    const mmdd = `${date.slice(5, 7)}/${date.slice(8, 10)}`;
    const t = Math.floor(rand() * 10);
    switch (t) {
      case 0:
        return `SQ *${name} ${digits(4)} ${city.slice(0, 13)} ${st}`;
      case 1:
        return `POS DEBIT ${name} #${digits(4)}`;
      case 2:
        return `${name} ${digits(6)} ${city} ${st}`;
      case 3:
        return `TST* ${name} ${city.slice(0, 10)}`;
      case 4:
        return `PURCHASE AUTHORIZED ON ${mmdd} ${name} ${city} ${st} S${digits(15)} CARD ${digits(4)}`;
      case 5:
        return `ACH DEBIT ${name} PPD ID: ${digits(10)}`;
      case 6:
        return `CHECKCARD ${mmdd.replace('/', '')} ${name} ${digits(23)}`;
      case 7:
        return `PAYPAL *${name.replace(/\s+/g, '')}`;
      default:
        return name;
    }
  };

  const rows: BenchRow[] = [];
  const perCategory = 165;
  SPECS.forEach((s, ci) => {
    const cat = categories[ci]!;
    for (let i = 0; i < perCategory; i++) {
      const day = 1 + Math.floor(rand() * 365);
      const d = new Date(Date.UTC(2025, 9, 1) + day * 86_400_000).toISOString().slice(0, 10);
      const [lo, hi] = s.range;
      const dollars = lo + rand() * (hi - lo);
      const cents = BigInt(Math.trunc(dollars * 100));
      const raw = noisy(pick(s.merchants), d);
      rows.push({
        id: `${cat.id}-${String(i).padStart(3, '0')}`,
        // Stratified: every 5th row of each category is held out.
        split: i % 5 === 4 ? 'test' : 'train',
        entityType: s.cat.entityType,
        accountType: pick(s.accounts),
        payee: raw,
        description: raw,
        amountMinor: (cents === 0n ? -1n : cents).toString(),
        currency: 'USD',
        date: d,
        label: cat.name,
      });
    }
  });
  return { categories, rows };
}

const here = dirname(fileURLToPath(import.meta.url));
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { categories, rows } = generateBenchmark();
  mkdirSync(join(here, 'benchmark'), { recursive: true });
  writeFileSync(join(here, 'benchmark', 'categories.v1.json'), `${JSON.stringify(categories, null, 2)}\n`);
  writeFileSync(
    join(here, 'benchmark', 'categorize.v1.jsonl'),
    rows.map((r) => JSON.stringify(r)).join('\n') + '\n',
  );
  console.log(
    `wrote ${rows.length} rows (${rows.filter((r) => r.split === 'test').length} test) across ${categories.length} categories`,
  );
}
